import networkx as nx
G = nx.Graph()
for i in range(21):
    for j in range(i+1, 21):
        G.add_edge(i, j)
max_independent_set = 4
vertex_connectivity = 4
if nx.algorithms.approximation.independent_set(G) <= max_independent_set and nx.algorithms.connectivity.vertex_connectivity(G) >= vertex_connectivity:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
